export function catalogRoleByKey(key: string): CatalogRole | undefined { return CATALOG_ROLES.find((r) => r.key === key) }
export function catalogLookup(key: string): CatalogFeature | undefined {
  for (const r of CATALOG_ROLES) for (const s of r.sections) for (const f of s.features) if (f.key === key) return f
  return undefined
}
export function allCatalogFeatureKeys(): Set<string> {
  const out = new Set<string>()
  for (const r of CATALOG_ROLES) for (const s of r.sections) for (const f of s.features) out.add(f.key)
  return out
}
export const PERMISSION_KEYS: string[] = PERMISSIONS.map((p) => p.key)
export const isDefaultRole = (key: string): boolean => { const r = SYSTEM_ROLES.find((x) => x.key === key); return r ? r.is_default : true }
export const isPlatformRole = (key: string): boolean => !!SYSTEM_ROLES.find((x) => x.key === key)?.platform
export const systemRoleByKey = (key: string): SystemRole | undefined => SYSTEM_ROLES.find((x) => x.key === key)
